param(
    [string]$ScriptPath = (Join-Path $PSScriptRoot 'InfoNotebook.ps1')
)

$ErrorActionPreference = 'Stop'

function Assert-True {
    param(
        [bool]$Condition,
        [string]$Name
    )
    if (-not $Condition) {
        throw "FAIL: $Name"
    }
}

$scriptText = Get-Content -Path $ScriptPath -Raw
$gradeRulesText = Get-Content -Path (Join-Path $PSScriptRoot 'GradeRules.ps1') -Raw
$serverPrintText = Get-Content -Path (Join-Path $PSScriptRoot 'ServidorImpressao.ps1') -Raw
$workspaceRoot = Split-Path -Parent $PSScriptRoot
$launcherBatText = Get-Content -LiteralPath (Join-Path $workspaceRoot 'InfoNotebook.bat') -Raw
$launcherVbsText = Get-Content -LiteralPath (Join-Path $workspaceRoot 'InfoNotebook.vbs') -Raw

Assert-True ($scriptText -match "\`$form\.Text\s*=\s*'InfoNotebook'") 'titulo nativo evita marca duplicada'
Assert-True ($scriptText -match "\`$splash\.ClientSize\s*=\s*New-Object System\.Drawing\.Size\(520,\s*300\)") 'loading usa composicao compacta'
Assert-True ($scriptText -match "Preparando o InfoNotebook") 'loading comunica a inicializacao com hierarquia clara'
Assert-True ($scriptText -match "\`$splashStatusCard\.BackColor\s*=\s*\[System\.Drawing\.Color\]::FromArgb\(15,\s*18,\s*29\)") 'loading segue a superficie do novo tema'
Assert-True ($scriptText -notmatch 'New-Object System\.Windows\.Forms\.OpenFileDialog') 'loading nao interrompe a abertura para solicitar logo'
Assert-True (([regex]::Matches($scriptText, 'Get-CimInstance Win32_VideoController')).Count -eq 1) 'hardware consulta controladores de video uma unica vez'
Assert-True ($launcherBatText -match 'wscript\.exe\s+//B\s+//Nologo') 'atalho bat delega a inicializacao invisivel'
