Assert-True ($launcherVbsText -match 'shell\.Run\s+command,\s*0,\s*False') 'launcher executa sem janela de console'
Assert-True ($launcherVbsText -match '-NoProfile\s+-NonInteractive\s+-STA') 'launcher reduz custo e mantem WinForms em STA'
Assert-True ($scriptText -match "Start-Process wscript\.exe\s+-ArgumentList") 'central de testes tambem abre pelo launcher invisivel'
Assert-True ($scriptText -match 'CAIJ_TESTS_OWNER_BOUNDS') 'central de testes recebe a posicao atual do InfoNotebook'
Assert-True ($scriptText -match 'CAIJ_TESTS_OWNER_BOUNDS') 'central de testes recebe a posicao atual do InfoNotebook'
