$tokensPersistencia = $null
$errosPersistencia = $null
$astPersistencia = [System.Management.Automation.Language.Parser]::ParseFile(
    $ScriptPath,
    [ref]$tokensPersistencia,
    [ref]$errosPersistencia
)
Assert-True ($errosPersistencia.Count -eq 0) 'script principal pode ser analisado para testar persistencia'
foreach ($nomeFuncao in @('Import-ModelosManuaisUltimos', 'Get-ModeloManualUltimo', 'Save-ModeloManualUltimo')) {
    $funcaoAst = $astPersistencia.Find({
        param($node)
        $node -is [System.Management.Automation.Language.FunctionDefinitionAst] -and
        $node.Name -eq $nomeFuncao
    }, $true)
    Assert-True ($null -ne $funcaoAst) "funcao $nomeFuncao existe para teste funcional"
    Invoke-Expression $funcaoAst.Extent.Text
}

$diretorioTesteModelo = Join-Path ([System.IO.Path]::GetTempPath()) ('caij-modelo-manual-' + [Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $diretorioTesteModelo | Out-Null
try {
    $script:modeloManualUltimoArquivo = Join-Path $diretorioTesteModelo 'caij_ultimo_modelo_manual.json'
    $script:modelosManuaisUltimos = @{}
    Assert-True (Save-ModeloManualUltimo -Tipo 'Notebook' -Modelo 'Dell Inc. Latitude 3420') 'modelo Dell e gravado sem alterar o texto'
    Assert-True (Save-ModeloManualUltimo -Tipo 'Desktop' -Modelo 'Dell OptiPlex 7090') 'persistencia separa modelos por tipo'

    $script:modelosManuaisUltimos = @{}
    Import-ModelosManuaisUltimos
    Assert-True ((Get-ModeloManualUltimo -Tipo 'Notebook') -ceq 'Dell Inc. Latitude 3420') 'modelo Dell e restaurado exatamente apos recarregar'
    Assert-True ((Get-ModeloManualUltimo -Tipo 'Desktop') -ceq 'Dell OptiPlex 7090') 'modelo de outro tipo permanece independente'
    Assert-True ([string]::IsNullOrWhiteSpace((Get-ModeloManualUltimo -Tipo 'Monitor'))) 'tipo sem modelo nao herda dados de notebook'
}
finally {
    Remove-Item -LiteralPath $diretorioTesteModelo -Recurse -Force
}
