foreach ($nomeFuncaoConfig in @(
    'Format-CadastroOsCpuConfigLocal',
    'Format-CadastroOsArmazenamentoConfigLocal',
    'Format-CadastroOsRamConfigLocal',
    'Format-CadastroOsGpuConfigLocal',
    'Get-CadastroOsConfiguracaoValoresLocal',
    'Get-CadastroOsConfiguracaoAtualLocal',
    'Format-TecnicoCadastroObservacaoLocal',
    'Get-CadastroOsDiaPrefixoLocal',
    'New-CadastroOsObservacaoLocal'
)) {
    $funcaoConfigAst = $astPersistencia.Find({
        param($node)
        $node -is [System.Management.Automation.Language.FunctionDefinitionAst] -and
        $node.Name -eq $nomeFuncaoConfig
    }, $true)
    Assert-True ($null -ne $funcaoConfigAst) "funcao $nomeFuncaoConfig existe para testar CONFIG"
    Invoke-Expression $funcaoConfigAst.Extent.Text
}
foreach ($nomeFuncaoApple in @('Get-AppleDeviceRam', 'Get-AppleStorageFromModelNumber')) {
    $funcaoAppleAst = $astPersistencia.Find({
        param($node)
        $node -is [System.Management.Automation.Language.FunctionDefinitionAst] -and
        $node.Name -eq $nomeFuncaoApple
    }, $true)
    Assert-True ($null -ne $funcaoAppleAst) "funcao $nomeFuncaoApple existe para testar dados Apple"
    Invoke-Expression $funcaoAppleAst.Extent.Text
}
